351 
352   if (InstSPF == SPF_SMAX &&
353       PatternMatch::match(RHS, PatternMatch::m_ConstantInt(C)) &&
354       C->getValue() == Imm && Imm.isNegative() && Imm.isNegatedPowerOf2()) {
355 
