361             matchSelectPattern(MinInst, MinLHS, MinRHS).Flavor;
362         if (MinSPF == SPF_SMIN &&
363             PatternMatch::match(MinRHS, PatternMatch::m_ConstantInt(MinC)) &&
364             MinC->getValue() == ((-Imm) - 1))
